      <a className='md:mr-20 mr-3 p-2 border rounded-md bg-white text-black font-semibold' href="https://github.com/aruntech91/Counter-DApp">Source-Code</a>

    </div>
      <hr className=' mt-2 md:ml-20 ml-3 md:mr-20 mr-3' />
        <div className="rounded-md border mt-24 p-7 mr-3 ml-3 gap-y-5 items-center place-self-center">

          <ConnectWallet></ConnectWallet>
     <div className='mt-5'>
          <Counter />

          </div>
        </div>
    </div>
  );
}

export default App;
